import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])

    arr = []
    for i in range(n):
        if i + 1 < len(data):
            arr.append(int(data[i + 1]))
        else:
            arr.append(0)

    if n == 0:
        print()
        return

    even_sum = 0
    for i in range(0, n, 2):
        even_sum += arr[i]

    arr[0] = even_sum

    print(' '.join(map(str, arr)))

if __name__ == "__main__":
    main()
